constexpr size_t budget=32u*1024u*1024u;
struct SavedUnitIdentity {std::uint32_t stable=0,type=0,owner=0;bool alive=false;jass::Real x,y,facing;};
bool finite(jass::Real value){return std::isfinite(std::bit_cast<float>(value.bits()));}
