Bytes ScriptSession::encodeUnitIdentities(const jass::StableHandleMap& encodeHandle) const {
    if(!runtime_.snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("Unit identity snapshot requires a quiescent local session");std::vector<std::uint32_t> handles;for(size_t i=0;i<objects_.size();++i)if(objects_[i].kind==NativeKind::Unit)handles.push_back(handleBase+std::uint32_t(i));if(!handles.empty() && !encodeHandle)throw std::runtime_error("Unit identity snapshot requires handle mapping");for(auto& [id,unit]:units_)if(!unit || !alive(id,NativeKind::Unit) || unit->handle!=id || unit->removing)throw std::runtime_error("Invalid live unit identity");SnapshotWriter out(budget-64);out.u32(tag("SUID"));out.u32(1);out.text(world_->resources().mapDigest(),64);out.u64(std::bit_cast<std::uint64_t>(simulationTime_));out.size(handles.size());std::set<std::uint32_t> stable;
    for(auto id:handles){auto& object=objects_[id-handleBase];auto mapped=encodeHandle("unit",id);if(!mapped || !stable.insert(mapped).second)throw std::runtime_error("Invalid unit identity mapping");out.u32(mapped);out.u32(object.alive?1:0);if(!object.alive)continue;auto found=units_.find(id);if(found==units_.end() || !found->second || found->second->removing || found->second->handle!=id)throw std::runtime_error("Invalid live unit identity");auto& unit=*found->second;if(unit.owner>=16 || !unit.type || !finite(unit.x) || !finite(unit.y) || !finite(unit.facing))throw std::runtime_error("Invalid unit identity values");out.u32(unit.type);out.u32(unit.owner);out.u32(unit.x.bits());out.u32(unit.y.bits());out.u32(unit.facing.bits());}
    return sealSnapshot(out.finish(),budget);
}
std::map<std::uint32_t,std::uint32_t> ScriptSession::rebuildUnitIdentities(std::span<const std::uint8_t> bytes) {
    if(!runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || unitRecoveryIncomplete_ || !units_.empty() || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || liveObjects(NativeKind::Event) || std::any_of(ais_.begin(),ais_.end(),[](const auto& ai){return bool(ai);}))throw std::runtime_error("Unit identity rebuild requires an idle local session before map main");for(auto& object:objects_)if(object.kind==NativeKind::Unit)throw std::runtime_error("Unit identity target already has unit handles");Binary in(openSnapshot(bytes,budget));in.expect(tag("SUID"));if(in.u32()!=1 || snapshotText(in,64)!=world_->resources().mapDigest())throw std::runtime_error("Unit identity snapshot map mismatch");auto time=std::bit_cast<double>(snapshotU64(in));if(!std::isfinite(time) || time!=simulationTime_)throw std::runtime_error("Unit identity snapshot clock mismatch");auto count=in.count(8,1048576);if(count>1048576-objects_.size())throw std::runtime_error("Unit identity object budget exceeded");std::vector<SavedUnitIdentity> saved;saved.reserve(count);std::set<std::uint32_t> stable;auto& data=definitions();for(unsigned i=0;i<count;++i){SavedUnitIdentity value;value.stable=in.u32();auto alive=in.u32();if(!value.stable || !stable.insert(value.stable).second || alive>1)throw std::runtime_error("Invalid unit identity mapping");value.alive=alive!=0;if(value.alive){value.type=in.u32();value.owner=in.u32();value.x=jass::Real::fromBits(in.u32());value.y=jass::Real::fromBits(in.u32());value.facing=jass::Real::fromBits(in.u32());if(value.owner>=16 || !data.contains(value.type) || !finite(value.x) || !finite(value.y) || !finite(value.facing))throw std::runtime_error("Invalid unit identity values");}saved.push_back(value);}in.finish();std::map<std::uint32_t,std::uint32_t> result;struct Guard{bool& failed;bool done=false;~Guard(){if(!done)failed=true;}}guard{failed_};
    for(auto& value:saved){std::uint32_t id=0;if(value.alive){id=createUnit(value.owner,value.type,value.x,value.y,value.facing,0,nullptr,false,true).bits;if(!alive(id,NativeKind::Unit) || !units_.contains(id) || units_.at(id)->type!=value.type || units_.at(id)->owner!=value.owner)throw std::runtime_error("Unit identity creation differs");auto unit=units_.at(id);unit->x=value.x;unit->y=value.y;unit->facing=value.facing;unitFootprint(*unit);}else{if(objects_.size()>=1048576)throw std::runtime_error("Unit identity object budget exceeded");id=handleBase+std::uint32_t(objects_.size());Object object{NativeKind::Unit,false,std::monostate{}};object.localNetworkOrdinal=std::uint32_t(localNetworkObjects_.size()+1);localNetworkObjects_.push_back(id);objects_.push_back(std::move(object));}result.emplace(value.stable,id);}++fogRevision_;unitIdentityHandles_=result;unitRecoveryIncomplete_=true;guard.done=true;return result;
}
